const win: IframeDesignProps = window as any;
const { design, moduleStore } = win;


export class EditText {

    item: DesignListItem
    paths: string[];

    value: string;
    constructor(item: DesignListItem, paths: string[]){
        this.item = item;
        this.paths = paths;
        this.value = _.get(this.item, paths);
        makeObservable(this, {
            value: observable,
            onChange: action
        })
    }

    onChange = (val: string) => {
        this.value = val;
        this.item.isEdit = true;
        _.set(this.item, this.paths, val);
    }
}

export class HtmlEditStore {
    page: CustomPageStore;
    item: DesignListItem;
    dom: HTMLElement;
    x: number;
    y: number;

    rect: DOMRect;
    children: DesignListItem[] = [];



    texts: EditText[] = [];



    getChildren = () => {
        const list = Object.values(design.listNode);
        this.children = list.filter((o) => o.parentId == this.item.id);
    }


     /**
     * 深度对比，是否存在text 节点
     * @param node 要检查的DOM节点
     */
     hasTextNode = (text: string, item: DesignListItem) => {
        const element = moduleStore.elements.get(item.key);
        const { source } = element;

        const parseBuilders = (paths: string[], dItem: DesignListItem) => {
            switch(paths[0]){
                case 'props':   // props 从父级传入
                    const module = design.pages[dItem.moduleId]!;
                    const list = design.pageNode[module.uid];
                    console.log('list', list)
                    for (const option of list) {
                        if(_.get(option, paths) == text){
                            // console.log('parentIds', design.pageNode[module.uid])
                            this.texts.push(new EditText(option, paths))
                        }{
                            // else if(option.builders.length && option.builders.) 多层props 逻辑暂未开发
                        }
                    }
                break;
                default:
                    // const module = design.pages[dItem.moduleId]!;
                    // const list = design.pageNode[module.uid];
                    // console.log('list', list, design.listNode[dItem.parentId])
            }
        }

        switch(source){ // 所属来源
            case "html":
                if(item.props.children == text){
                    this.texts.push(new EditText(item, ['props', 'children']))
                }else if(item.builders.length){     // 存在builders 进行解析
                    for (const builder of item.builders) {
                        if(builder.key.join('') == 'children'){
                            parseBuilders(builder.path, item);
                        }
                    }
                }
            break;
        }
        
        // 递归检查子节点
        console.log('item', text, item, element);
     }

    /**
     * 修改Text 节点
     */
    updateAllEdit = (node: HTMLElement) => {
        const text = node.textContent;
        const item = this.children.find((o) => o.props.value == text);
        if(item){  // 获取到结果
            this.texts.push(new EditText(item, ['props', 'value']))
        }
    }

    


    /**
     * 判断是否可以直接编辑
     */
    isHtmlDomEdit = () => {
        const list = Array.from(this.dom.childNodes) as HTMLElement[];
    
        // 判断是否有text 节点
        if(Array.isArray(list)){
            if(list.some((o) => o.nodeType == Node.TEXT_NODE)){
                if(list.length == 1){   // 没有额外的信息，单一节点
                    // 存在单个文本信息
                    this.hasTextNode(list[0].textContent, this.item)
                }else {
                    // 存在多个文本信息
                    this.getChildren();
                    for (const node of list) {
                        if (node.nodeType === Node.TEXT_NODE) {
                            this.updateAllEdit(node);
                        }
                    }
                }
            }
        }
    }


    // 用户出发click 事件
    onClick = (event) => {
        this.x = event.clientX
        this.y = event.clientY
        if(!this.menuDom){
            this.createMenu();
        }
    }


    menuDom: any;
    /**
     * 创建菜单
     */
    createMenu = () => {
        const dom = document.createElement('div');
        ReactDOM.render(React.createElement(Menu, { store: this }), dom);
        document.body.appendChild(dom);
        this.menuDom = dom; // 保存菜单DOM引用
    }

    /**
     * 销毁菜单
     */
    closeMenu = async () => {
        if (this.menuDom) {
            ReactDOM.unmountComponentAtNode(this.menuDom); // 卸载组件
            document.body.removeChild(this.menuDom); // 从DOM中移除
            this.menuDom = null; // 清空引用
            // 需要重新加载的模块
            const moduleNode: Record<string, boolean> = {};
            for (const o of this.texts) {
                const { isEdit, moduleId, pageId, props, paths } = o.item;
                if(isEdit){
                    const page = design.pages[moduleId || pageId];
                    moduleNode[moduleId || pageId] = true;  // 记录要更新模块
                    page.isSave = true; // 标记模块状态
                    _.set(page, [...paths, 'props'], props);    // 更新页面组件状态
                    o.item.isEdit = false;  // 重置掉当前状态
                }
            }
            const keys = Object.keys(moduleNode);
            if(keys.length){
                for (const key of keys) {
                    // 需要重新加载页面
                    const page = design.pages[key];
                    let jsxRender = await page.getRenderText();
                    console.log('jsxRender', jsxRender)
                    if(page.isPage){
                        dev.buildPages(page.uid, { jsxRender })
                    }else {
                        dev.loadModules(page.uid, { jsxRender })
                    }
                }
                dev.updateKey();
            }
        }
    }

    init = () => {
        this.isHtmlDomEdit();
    }


    /**
     * 清除副作用
     */
    unInit = () => {
        this.closeMenu();
    }

    constructor(page: CustomPageStore, item: DesignListItem, dom: HTMLElement){
        this.page = page;
        this.item = item;
        this.dom = dom;

        this.init();
    }
    

}


class IframeStore {


    highlightElement(element) {
        // 清除之前的高亮
        document.querySelectorAll('.selected-highlight').forEach(el => {
          el.classList.remove('selected-highlight');
        });
      
        // 添加高亮样式
        if (element) {
          element.classList.add('selected-highlight');
        }
    }

    selectDOM: HTMLElement;
    selectKey: string;
    editStore: HtmlEditStore;


    // 判断dom 是否可以被解析
    getDomKey = (dom: HTMLElement) => {
        
        // console.log('dom', dom, dom.nodeType, typeof dom, Node.COMMENT_NODE)
        if(!dom.dataset) return false;
        const keys = Object.keys(dom.dataset).map((o) => o.toLocaleLowerCase().replace('-', '').slice(1));

        for (const key of keys) {
            if(design.listNode[key]){
                // this.selectKey = key;
                // console.log('listNode', this.listNode[key])
                return key;
            }
        }

        return false;
    }
    

    /**
     * dom 解析事件
     */
    clickDom = (event) => {
        event.stopPropagation();
        event.preventDefault();
        


        const item = design.listNode[this.selectKey];
        if(this.editStore){
            if(this.editStore.item.id == item.id) {
                this.editStore.onClick(event);
                return;
            }else {
                // 卸载当前配置信息
                this.editStore.unInit();
            }
        }

        const { target } = event;

        if(item.pageId){
            const page = design.pages[item.pageId];
            this.editStore = new HtmlEditStore(page, item, target);
            // console.log('当前选中的页面', this.selectKey, page, item, this.selectDOM)
            
        }else if(item.moduleId){
            const module = design.pages[item.moduleId];
            this.editStore = new HtmlEditStore(module, item, target);
            // console.log('当前选中的模块', this.selectKey, module, item, this.selectDOM)
        }
        
        
        // this.editStore.rect = this.selectDOM.getBoundingClientRect();
        this.editStore.onClick(event);

    }

    clearDom = (dom: HTMLElement) => {
        // 清除之前的高亮元素
        document.querySelectorAll('.selected-highlight').forEach(el => {
            el.remove();
        });
        dom.removeEventListener('click', this.clickDom);
    }


    /**
     * dom 解析
     */
    parseDom = (dom: HTMLElement) => {
        if (dom) {
            const rect = dom.getBoundingClientRect();
            const highlightDiv = document.createElement('div');
            highlightDiv.style.position = 'fixed';
            highlightDiv.style.top = `${rect.top}px`;
            highlightDiv.style.left = `${rect.left}px`;
            highlightDiv.style.width = `${rect.width}px`;
            highlightDiv.style.height = `${rect.height}px`;
            highlightDiv.style.border = '1px solid red';
            highlightDiv.style.pointerEvents = 'none';
            highlightDiv.classList.add('selected-highlight');
            document.body.appendChild(highlightDiv);
        }
        dom.addEventListener('click', this.clickDom);
        
    }

    handleMouseMove = (event) => {
        const x = event.clientX;
        const y = event.clientY;
      

        if(this.editStore && this.editStore.menuDom) {  // 当前编辑器是否存在菜单
            return null;
        }
        // 获取当前鼠标所在的元素
        const element = document.elementFromPoint(x, y) as HTMLElement;
        
        if(element && this.selectDOM != element){
            const key = this.getDomKey(element);
            if(key){
                this.selectKey = key;
                if(this.selectDOM) this.clearDom(this.selectDOM);
                this.parseDom(element);
                this.selectDOM = element;
            }

        }
      
    }


    setTextToSpanKey = (node: HTMLElement, list: DesignListItem[]) => {
        const text = node.textContent;
        const item = list.find((o) => o.props.value == text);
        if(item){
            const span = document.createElement('span');
            span.setAttribute(`data-v-${item.id}`, "");
            span.style.all = 'unset';   // 无样式设置
            span.textContent = node.textContent; // 将text值复制给span标签
            node.parentNode.insertBefore(span, node);
            node.parentNode.removeChild(node);
        }
    }
    

    /**
     * 转换所有text 元素
     */
    textToSpan = () => {
        const list = Object.values(design.listNode);
        const loop = (node) => {
            const nodes = Array.from(node.childNodes) as HTMLElement[];

            const texts = nodes.filter((o) => o.nodeType == Node.TEXT_NODE);
            const key = this.getDomKey(node);
            const childrens = key? list.filter((o) => o.parentId == key) : []
            for (const item of nodes) {
                if(item.nodeType == Node.TEXT_NODE){
                    if(key && list.length && texts.length){
                        this.setTextToSpanKey(item, childrens);
                    }
                }else {
                    loop(item)
                }
            }
        }

        loop(document.body)
    }

    /**
     * 监听元素事件
     */
    onSelectDom = () => {
        document.addEventListener('mousemove', this.handleMouseMove, true);
    }


    /**
     * 初始化编辑器
     */
    init = async () => {
        // this.textToSpan();
        // 监听选择HTML
        this.onSelectDom();
    }
}

export default new IframeStore;