import React, { useMemo } from 'react';
import { Button, Descriptions, Input, InputProps, TextAreaProps, Tooltip } from "@arco-design/web-react";
import classNames from 'classnames';
import styles from './index.module.less';
import i18next from 'i18next';
import Language from './Language';
import { IconLanguage } from '@arco-design/web-react/icon';
import { getTranslation, isTranslation } from '@/utils/is';
import zhCN from "@code/locales/lang/zh-CN";
import enUS from '@code/locales/lang/en-US';


interface TranslationProps extends TextAreaProps {
    isI18n: boolean;
}
const Translation = ({ isI18n, ...props }: TranslationProps) => {

    const isTrans = useMemo(() => {
        if(isI18n) return true;
        return isTranslation(props.value);
    },[props.value])

    const value = useMemo(() => {
        if(isI18n) {
            return props.value
        }else {
            if(isTrans) {
                const str = getTranslation(props.value)
                return str
            }
            return '';   
        }
    },[props.value])


    const onChange = (key) => {
        if(props.onChange){
            if(isI18n){
                props.onChange(key, {});
            }else {
                props.onChange(`$t{ ${key} }`, {})
            }
        }
    }


    return (
        <div style={{ position: 'relative' }}>
            <Input.TextArea
                placeholder="请输入"
                {...props}
                value={props.value}
                className={classNames(styles.input, props.className)}
            />
            <div style={{ position: 'absolute', right: 8, top: 8 }}>
                <Language
                    value={isTrans? props.value : ""}
                    onChange={onChange}
                    readOnly={props.readOnly}
                    trigger={
                        Boolean(zhCN[value])? (
                            <Tooltip
                                content={(
                                    <div>
                                        <span>中文：</span>
                                        <span>{zhCN[value]}</span>
                                        <br />
                                        <span>英文：</span>
                                        <span>{enUS[value]}</span>
                                    </div>
                                )}
                            >
                                <Button
                                    type="primary"
                                    icon={<IconLanguage />}
                                />
                            </Tooltip>
                        ):(
                            <Button
                                type={"default"}
                                icon={<IconLanguage />}
                            />
                        )
                    }
                />
            </div>
        </div>
    )
}

export default Translation