import React, { useMemo, useState, useEffect } from "react";
import { Popover, Button, Tooltip } from "@arco-design/web-react";
import { HtmlEditStore } from "@/store/iframeDesign";
import { useObserver } from "mobx-react-lite";
import { IconEdit, IconBgColors, IconSettings, IconStar } from "@arco-design/web-react/icon";
import './style.less';
import TextInput from "../components/text-input";


interface MenuProps {
    store: HtmlEditStore;
}

type TypeText = 'none' | 'text' | "styles" | "events"
const Menu = ({ store }: MenuProps) => {

    return useObserver(() => {

        const { x, y, closeMenu } = store;
        const [type, setType] = useState<TypeText>('none');

        const position = useMemo(() => {
            // 根据x,y坐标计算最佳弹出位置
            const windowWidth = window.innerWidth;
            const windowHeight = window.innerHeight;
            
            if (y < windowHeight / 2) {
                // 上半部分
                if (x < windowWidth / 3) {
                    return 'bl';
                } else if (x > windowWidth * 2 / 3) {
                    return 'br';
                } else {
                    return 'bottom';
                }
            } else {
                // 下半部分
                if (x < windowWidth / 3) {
                    return 'tl';
                } else if (x > windowWidth * 2 / 3) {
                    return 'tr';
                } else {
                    return 'top';
                }
            }
        }, [x, y]);

        const textRender = useMemo(() => {
            if(type !== 'text') return null;
            return store.texts.map((o, i) => (
                <TextInput store={o} key={i} />
            ))
        },[type])

        return (
            <Popover 
                popupVisible={true}
                trigger="hover"
                onVisibleChange={() => {
                    // 关闭流程
                    closeMenu();
                }}
                style={{ padding: 0, margin: 0 }}
                className={"popover-design"}
                position={position}
                content={(
                    <React.Fragment>
                        <Button.Group>
                            {Boolean(store.texts.length) && (
                                <Tooltip content="文本修改">
                                    <Button type='primary' icon={<IconEdit />} onClick={() => setType('text')}/>
                                </Tooltip>
                            )}
                            <Tooltip content="样式设计">
                                <Button type='primary' icon={<IconBgColors />} onClick={() => setType('styles')} />
                            </Tooltip>
                            <Tooltip content="事件配置">
                                <Button type='primary' icon={<IconSettings />} onClick={() => setType('events')} />
                            </Tooltip>
                        </Button.Group>
                        {textRender}
                    </React.Fragment>
                )}
            >
                <div 
                    style={{
                        position: "fixed",
                        left: x,
                        top: y,
                        width: 1,
                        height: 1,
                    }}
                >
                </div>
            </Popover>
        )
    })
}

export default Menu;