import { EditText } from "@/store/iframeDesign";
import React from "react";
import Translation from '@/components/custom/Translation/textarea';
import { useObserver } from "mobx-react-lite";


interface TextInputProps {
    store: EditText;
}
const TextInput = ({ store }: TextInputProps) => {


    return useObserver(() => {

        const { value, onChange } = store;
        
        return (
            <div style={{ width: 300, overflowY: 'auto', marginTop: 6 }}>
                <Translation value={value} onChange={onChange} isI18n />
            </div>
        )  
    })
}


export default TextInput;